import groovy.json.JsonSlurper
import java.text.SimpleDateFormat
import java.util.TimeZone

// ================= INPUT EXTRACTION =================
def rawFdesInput = {{ n_Dugi6.outputs }}
def rawTasksInput = {{ n_P7X4Z.outputs }}
def rawAllOrgInput = {{ n_SISbB.outputs }}


def extractList = { rawInput ->
    if (!rawInput) return []
    def data = rawInput
    if (data instanceof String) {
        try {
            data = new JsonSlurper().parseText(data)
        } catch (Exception e) {
            return []
        }
    }
    if (data instanceof Map && data.containsKey('objects')) {
        return data.objects ?: []
    }
    if (data instanceof List) {
        return data
    }
    return []
}

def fdesInput = extractList(rawFdesInput)
def tasksInput = extractList(rawTasksInput)
def allOrgInput = extractList(rawAllOrgInput)

// Normalise DB field names (db_fdse uses mail_id / Manager / updatedManagerEmail)
def normalizeFde = { rec ->
    def p = (rec instanceof Map && rec.properties instanceof Map) ? rec.properties : rec
    if (p instanceof Map) {
        try {
            if (!p.get('mailId') && p.get('mail_id')) p.put('mailId', p.get('mail_id'))
            if (!p.get('manager') && p.get('Manager')) p.put('manager', p.get('Manager'))
            if (!p.get('managerEmail') && p.get('updatedManagerEmail')) p.put('managerEmail', p.get('updatedManagerEmail'))
        } catch (Exception e) { }
    }
    return rec
}
fdesInput.each { normalizeFde(it) }
allOrgInput.each { normalizeFde(it) }

// Select the people to report on (done here instead of in the fetch step, so empty inputs never break the run):
//  - direct reports of the given manager (by email, else by name)
//  - narrowed to one FDE when 'fdse' is passed
//  - if that yields nobody, the person themself (FDSE detail page for someone with no reports)
def _clean = { Object s -> def t = (s == null ? '' : s.toString()).trim().toLowerCase(); (t == 'null') ? '' : t }
def _selfMail = _clean({{ n_OCUWB.outputs.managerEmail }})
def _selfName = _clean({{ n_OCUWB.outputs.manager }})
def _fdseName = _clean({{ n_OCUWB.outputs.fdse }})
def _p = { rec -> (rec instanceof Map && rec.properties instanceof Map) ? rec.properties : rec }
def _s = { v -> (v ?: '').toString().trim().toLowerCase() }
def _reports = allOrgInput.findAll { rec ->
    def p = _p(rec)
    def mgrMail = _s(p.get('updatedManagerEmail') ?: p.get('managerEmail'))
    def mgrName = _s(p.get('Manager') ?: p.get('manager'))
    (_selfMail && mgrMail == _selfMail) || (!_selfMail && _selfName && mgrName == _selfName)
}
if (_fdseName) _reports = _reports.findAll { rec -> _s(_p(rec).get('fde')) == _fdseName }
if (!_reports) {
    _reports = allOrgInput.findAll { rec ->
        def p = _p(rec)
        def m = _s(p.get('mailId') ?: p.get('mail_id'))
        def nm = _s(p.get('fde'))
        (_fdseName && nm == _fdseName) || (_selfMail && m == _selfMail) || (_selfName && nm == _selfName)
    }
}
fdesInput = _reports

// Status configuration (case-insensitive)
def COMPLETED_STATUSES = ['done', 'completed']
def IN_PROGRESS_STATUSES = ['in progress', 'in-progress']

def OWNER_KEY = 'o' + 'wner'

def toIntSafe = { v ->
    if (v == null) return 0
    if (v instanceof Number) return v.intValue()
    def s = v.toString().trim()
    if (!s) return 0
    try {
        return Math.round(Double.parseDouble(s)) as int
    } catch (Exception e) {
        return 0
    }
}

def toLongSafe = { v ->
    if (v == null) return null
    if (v instanceof Number) return v.longValue()
    def s = v.toString().trim()
    if (!s) return null
    try {
        return Long.parseLong(s)
    } catch (Exception e) {
        try {
            return Math.round(Double.parseDouble(s))
        } catch (Exception e2) {
            return null
        }
    }
}

// A task with no recorded story points defaults to this instead of 0, so a
// blank/missing taskStoryPoints value can't silently zero the task out of the
// utilisation calc.
int DEFAULT_STORY_POINTS_IF_MISSING = 1

def storyPointsOf = { task ->
    int raw = toIntSafe(task.taskStoryPoints ?: task.TaskStoryPoints)
    return raw > 0 ? raw : DEFAULT_STORY_POINTS_IF_MISSING
}

// Fixed weekly capacity per FDE: 8 pts/day x 6 working days.
double WEEKLY_CAPACITY = 48.0d
def nowMillis = System.currentTimeMillis()

// ================= "THIS WEEK" WINDOW (for completed-task credit) =================
// Avg utilisation shouldn't crater to 0 the moment a sprint wraps up — work
// finished earlier this week still consumed real capacity. There's no
// dedicated "date marked Completed" field in the data, so modifiedTime
// (falling back to lastPlatformUpdateOn) is used as a proxy: it's not
// perfectly precise, since ANY edit bumps it, but it's the closest available
// signal to "when this task was last touched," which for a Completed task is
// usually the moment it was closed out.
// Assumption: IST. Change TZ below if the team operates elsewhere.
def TZ = TimeZone.getTimeZone('Asia/Kolkata')

def startOfDay = { long millis ->
    def cal = Calendar.getInstance(TZ)
    cal.setTimeInMillis(millis)
    cal.set(Calendar.HOUR_OF_DAY, 0)
    cal.set(Calendar.MINUTE, 0)
    cal.set(Calendar.SECOND, 0)
    cal.set(Calendar.MILLISECOND, 0)
    return cal
}

def todayCal = startOfDay(nowMillis)
def mondayCal = todayCal.clone()
int dow = mondayCal.get(Calendar.DAY_OF_WEEK)  // SUNDAY=1 ... SATURDAY=7
int daysSinceMonday = ((dow - Calendar.MONDAY) + 7) % 7
mondayCal.add(Calendar.DAY_OF_MONTH, -daysSinceMonday)
def thisWeekStartMillis = mondayCal.getTimeInMillis()

// True if this Completed task's modifiedTime/lastPlatformUpdateOn proxy falls
// within [Monday 00:00, now]. Tasks with no usable timestamp return false
// (can't be time-placed) rather than guessing — same principle as blank eta
// elsewhere in this script: don't silently invent a date.
def completedThisWeek = { task ->
    def completedMillisObj = toLongSafe(task.modifiedTime ?: task.lastPlatformUpdateOn)
    if (completedMillisObj == null) return false
    return completedMillisObj >= thisWeekStartMillis && completedMillisObj <= nowMillis
}

// ================= PRE-STEP: Collect Known FDE Names AND build an Email -> FDE-name lookup =================
def knownFdeNames = [] as Set
def emailToFdeNameLower = [:]

def registerFde = { props, boolean overwrite ->
    def name = props.fde?.toString()?.trim()
    def mail = props.mailId?.toString()?.trim()?.toLowerCase()
    if (name) knownFdeNames << name.toLowerCase()
    if (mail && name) {
        if (overwrite || !emailToFdeNameLower.containsKey(mail)) {
            emailToFdeNameLower[mail] = name.toLowerCase()
        }
    }
}
fdesInput.each { rec -> registerFde(rec.properties ?: rec, true) }
allOrgInput.each { rec -> registerFde(rec.properties ?: rec, false) }
def knownFdeNamesSorted = knownFdeNames.sort { -it.length() }

def SPLIT_PATTERN = /(?i),|&|\+|\band\b|\//

def matchNamesByText = { String rawText ->
    if (!rawText) return []
    boolean hasDelimiter = rawText =~ SPLIT_PATTERN
    def matched
    if (hasDelimiter) {
        def segments = rawText.split(SPLIT_PATTERN)*.trim().findAll { it }
        matched = segments.collect { seg ->
            knownFdeNamesSorted.find { fdeName -> seg == fdeName || seg.contains(fdeName) || fdeName.contains(seg) }
        }.findAll { it != null }
        if (matched.isEmpty()) matched = segments
    } else {
        def remaining = rawText
        def contained = []
        knownFdeNamesSorted.each { fdeName ->
            if (remaining.contains(fdeName)) {
                contained << fdeName
                remaining = remaining.replaceFirst(java.util.regex.Pattern.quote(fdeName), " ")
            }
        }
        matched = contained ?: [rawText]
    }
    return matched
}

// Email-first, name-fallback matching — used for both owners and reviewers.
def matchPeople = { props, String listKey, String singleMailKey, String nameKey ->
    def emailCandidates = [] as Set
    def listRaw = props.get(listKey)
    if (listRaw instanceof List) {
        listRaw.each { e ->
            def es = e?.toString()?.trim()?.toLowerCase()
            if (es) emailCandidates << es
        }
    }
    def singleMail = props.get(singleMailKey)?.toString()?.trim()?.toLowerCase()
    if (singleMail) emailCandidates << singleMail

    def matched = emailCandidates.collect { email -> emailToFdeNameLower[email] }.findAll { it != null }.unique()

    if (matched.isEmpty()) {
        def rawName = props.get(nameKey)?.toString()?.trim()?.toLowerCase()
        matched = matchNamesByText(rawName)
    }
    return matched
}

// ================= STEP 1: Map Tasks by Owner (counts) + Compute Capacity Load =================
def assigneeTasksMap = [:].withDefault { [] }
def ownerLoadMap = [:].withDefault { 0.0d }
def reviewerLoadMap = [:].withDefault { 0.0d }

// A task's full (undivided) load, in points:
//  - Completed THIS WEEK (per the modifiedTime proxy above): full story points
//    x 1.0 — it consumed real capacity, no urgency multiplier applies since
//    there's no more "due date" risk once it's done.
//  - Completed, but not within this week (or no usable timestamp): 0 — it no
//    longer represents current-week load.
//  - Not started (Pending/etc.) and not overdue: 0 (not currently active work).
//  - In Progress, or overdue regardless of status: story points x urgency
//    multiplier. Urgency is based on eta when present; if eta is missing, the
//    multiplier defaults to 1.0 (normal priority) so the task still counts in
//    full rather than being dropped.
def computeTaskLoad = { task ->
    def status = task.status?.toString()?.toLowerCase()?.trim()

    if (status in COMPLETED_STATUSES) {
        if (!completedThisWeek(task)) return 0.0d
        int points = storyPointsOf(task)
        return points * 1.0d
    }

    int points = storyPointsOf(task)

    def etaMillisObj = toLongSafe(task.eta)
    boolean isOverdue = false
    Double multiplier = null

    if (etaMillisObj != null) {
        long diffDays = Math.floor((etaMillisObj - nowMillis) / 86400000.0d) as long
        if (diffDays < 0) {
            isOverdue = true
            multiplier = 1.25d
        } else if (diffDays <= 14) {
            multiplier = 1.0d
        } else if (diffDays <= 30) {
            multiplier = 0.5d
        } else {
            multiplier = 0.2d
        }
    }

    boolean isActiveWork = (status in IN_PROGRESS_STATUSES) || isOverdue
    if (!isActiveWork) return 0.0d

    double effectiveMultiplier = multiplier != null ? multiplier : 1.0d
    return points * effectiveMultiplier
}

tasksInput.each { rec ->
    def props = rec.properties ?: rec

    def matchedOwners = matchPeople(props, 'ownersList', 'ownerMail', OWNER_KEY).unique()
    def matchedReviewers = matchPeople(props, 'ReviewersList', 'reviewerMail', 'reviewer').unique()

    // --- Count-based bucket (unchanged behavior, drives the informational fields) ---
    if (!matchedOwners.isEmpty()) {
        boolean isShared = matchedOwners.size() > 1
        def taskClone = new HashMap(props)
        taskClone['_isSharedTask'] = isShared
        matchedOwners.each { ownerName -> assigneeTasksMap[ownerName] << taskClone }
    }

    // --- Capacity load, split across co-owners / reviewers ---
    double taskLoad = computeTaskLoad(props)
    if (taskLoad > 0) {
        if (!matchedOwners.isEmpty()) {
            double perOwner = taskLoad / matchedOwners.size()
            matchedOwners.each { ownerName -> ownerLoadMap[ownerName] = ownerLoadMap[ownerName] + perOwner }
        }
        if (!matchedReviewers.isEmpty()) {
            double reviewShare = (taskLoad * 0.2d) / matchedReviewers.size()
            matchedReviewers.each { reviewerName -> reviewerLoadMap[reviewerName] = reviewerLoadMap[reviewerName] + reviewShare }
        }
    }
}

// ================= STEP 2: Map Organizational Hierarchy (Direct Reports) & Metadata from Node 4 =================
def managerToReportsMap = [:].withDefault { [] }
def fdeNeededMap = [:]

allOrgInput.each { rec ->
    def props = rec.properties ?: rec
    def managerName = props.get('manager')?.toString()?.trim()?.toLowerCase()
    def fdeName = props.get('fde')?.toString()?.trim()
    def fdeMail = props.get('mailId')?.toString()?.trim()

    if (fdeName) {
        def fdeNeededVal = props.get('fdeNeeded')?.toString()?.trim() ?: "0"
        fdeNeededMap[fdeName.toLowerCase()] = fdeNeededVal
    }

    if (managerName && fdeName) {
        managerToReportsMap[managerName] << [
            fde: fdeName,
            mailId: fdeMail ?: ''
        ]
    }
}

// ================= STEP 3: Assemble Per-FDE Output =================
double simpleUtilisationSum = 0

def ownerUtilisationList = fdesInput.collect { rec ->
    def props = rec.properties ?: rec
    def fdeName = props.fde?.toString()?.trim() ?: 'Unknown Owner'
    def fdeKey = fdeName.toLowerCase()

    def assignedTasks = assigneeTasksMap[fdeKey] ?: []

    int sharedTasks = 0
    def accountSet = [] as Set

    def node2Accounts = props.get('accounts') ?: props.get('account')
    if (node2Accounts instanceof List) {
        node2Accounts.each { acct -> def a = acct?.toString()?.trim(); if (a) accountSet << a }
    } else if (node2Accounts) {
        node2Accounts.toString().split(',').each { acct -> def a = acct?.trim(); if (a) accountSet << a }
    }

    int completedFromStatus = 0
    int inProgressFromStatus = 0
    int overdueFromTasks = 0
    int totalStoryPoints = 0
    int completedStoryPoints = 0
    int inProgressStoryPoints = 0
    int completedThisWeekStoryPoints = 0

    assignedTasks.each { task ->
        def status = task.status?.toString()?.toLowerCase()?.trim()
        int points = storyPointsOf(task)
        totalStoryPoints += points

        if (status in COMPLETED_STATUSES) {
            completedFromStatus++
            completedStoryPoints += points
            if (completedThisWeek(task)) {
                completedThisWeekStoryPoints += points
            }
        } else if (status in IN_PROGRESS_STATUSES) {
            inProgressFromStatus++
            inProgressStoryPoints += points
        }

        if (task._isSharedTask) sharedTasks++

        def acct = task.account?.toString()?.trim()
        if (acct) accountSet << acct

        // Informational only — does not affect the percentage.
        if (!(status in COMPLETED_STATUSES)) {
            def etaMillis = toLongSafe(task.eta)
            if (etaMillis != null && etaMillis < nowMillis) overdueFromTasks++
        }
    }

    int totalTasks = assignedTasks.size()
    int completedTasks = completedFromStatus
    int inProgressTasks = inProgressFromStatus
    int activeTasks = totalTasks - completedTasks
    int pendingTasks = Math.max(0, totalTasks - completedTasks - inProgressTasks)
    int overdueTasks = overdueFromTasks
    int activeStoryPoints = completedStoryPoints + inProgressStoryPoints

    // ---- Capacity-normalized utilisation (this drives the actual %) ----
    // ownedLoad/reviewingLoad now blend: (a) points from tasks completed THIS
    // WEEK, plus (b) points from tasks currently In Progress/overdue — so
    // utilisation reflects "capacity consumed this week" rather than only
    // "what's active right now."
    double ownedLoad = ownerLoadMap[fdeKey] ?: 0.0d
    double reviewingLoad = reviewerLoadMap[fdeKey] ?: 0.0d
    double totalLoad = ownedLoad + reviewingLoad

    double percentage = (totalLoad / WEEKLY_CAPACITY) * 100.0d
    double roundedPercentage = Math.round(percentage * 100) / 100.0d

    double roundedOwnedLoad = Math.round(ownedLoad * 100) / 100.0d
    double roundedReviewingLoad = Math.round(reviewingLoad * 100) / 100.0d
    double roundedTotalLoad = Math.round(totalLoad * 100) / 100.0d

    simpleUtilisationSum += roundedPercentage

    def directReportsList = managerToReportsMap[fdeKey] ?: []
    def reportNames = directReportsList.collect { it.fde }
    def fdeNeededVal = fdeNeededMap[fdeKey] ?: props.get('fdeNeeded')?.toString()?.trim() ?: "0"

    def resMap = [:]
    resMap.put(OWNER_KEY, fdeName)
    resMap.put('mailId', props.mailId ?: props.email ?: '')
    resMap.put('designation', props.designation ?: 'Unknown')
    resMap.put('manager', props.manager ?: 'Unassigned')
    resMap.put('fdeNeeded', fdeNeededVal)
    resMap.put('totalTasks', totalTasks)
    resMap.put('completedTasks', completedTasks)
    resMap.put('inProgressTasks', inProgressTasks)
    resMap.put('activeTasks', activeTasks)
    resMap.put('pendingTasks', pendingTasks)
    resMap.put('totalStoryPoints', totalStoryPoints)
    resMap.put('completedStoryPoints', completedStoryPoints)
    resMap.put('completedThisWeekStoryPoints', completedThisWeekStoryPoints)
    resMap.put('inProgressStoryPoints', inProgressStoryPoints)
    resMap.put('activeStoryPoints', activeStoryPoints)
    resMap.put('sharedTasks', sharedTasks)
    resMap.put('overdueTasks', overdueTasks)
    resMap.put('weeklyOwnedLoad', roundedOwnedLoad)
    resMap.put('weeklyReviewingLoad', roundedReviewingLoad)
    resMap.put('weeklyTotalLoad', roundedTotalLoad)
    resMap.put('weeklyCapacity', WEEKLY_CAPACITY)
    resMap.put('utilisationPercentage', roundedPercentage)
    resMap.put('utilisationFormatted', String.format("%.2f%%", roundedPercentage))
    resMap.put('totalAccounts', accountSet.size())
    resMap.put('accountNames', accountSet.toList())
    resMap.put('directReportsCount', directReportsList.size())
    resMap.put('directReportsNames', reportNames)
    resMap.put('directReportsDetails', directReportsList)

    return resMap
}

// ================= STEP 4: Overall Average Efficiency =================
// Each person's % is already capacity-normalized (points / 48), so the org-level
// figure is a plain average across FDEs rather than weighted by task/point volume.
double avgEfficiencyVal = fdesInput.size() > 0 ? (simpleUtilisationSum / fdesInput.size()) : 0.0d
double roundedAvgEfficiency = Math.round(avgEfficiencyVal * 100) / 100.0d

// ================= OUTPUT =================
return [
    result: ownerUtilisationList,
    weightedAvgEfficiency: roundedAvgEfficiency,
    weightedAvgEfficiencyFormatted: String.format("%.2f%%", roundedAvgEfficiency)
]

import groovy.json.JsonSlurper

// ================= INPUT EXTRACTION =================
def rawFdesInput = {{ n_Dugi6.outputs }}
def rawTasksInput = {{ n_P7X4Z.outputs }}
def rawAllOrgInput = {{ n_SISbB.outputs }}

if (binding.hasVariable('parameters')) {
    rawFdesInput = parameters.fdes ?: parameters.leads
    rawTasksInput = parameters.tasks ?: parameters.accounts
    if (parameters.containsKey('allOrg')) rawAllOrgInput = parameters.allOrg
}

// Extraction helper handling raw JSON strings, wrapped object maps, or lists
def extractList = { rawInput ->
    if (!rawInput) return []
    def data = rawInput
    if (data instanceof String) {
        try {
            data = new JsonSlurper().parseText(data)
        } catch (Exception e) {
            return []
        }
    }
    if (data instanceof Map && data.containsKey('objects')) {
        return data.objects ?: []
    }
    if (data instanceof List) {
        return data
    }
    return []
}

def fdesInput = extractList(rawFdesInput)
def tasksInput = extractList(rawTasksInput)
def allOrgInput = extractList(rawAllOrgInput)

// Status configuration (case-insensitive)
def COMPLETED_STATUSES = ['done', 'completed']
def IN_PROGRESS_STATUSES = ['in progress', 'in-progress']

def OWNER_KEY = 'o' + 'wner'

// ================= STEP 1: Map Tasks by ownerMail =================
def ownerMailTasksMap = [:].withDefault { [] }

tasksInput.each { rec ->
    def props = rec.properties ?: rec
    def taskOwnerMail = props.get('ownerMail')?.toString()?.trim()?.toLowerCase()

    if (!taskOwnerMail) {
        taskOwnerMail = props.get(OWNER_KEY)?.toString()?.trim()?.toLowerCase()
    }

    if (taskOwnerMail) {
        ownerMailTasksMap[taskOwnerMail] << props
    }
}

// ================= STEP 2: Map Hierarchy (Direct Reports) from Org Input =================
def managerToReportsMap = [:].withDefault { [] }

allOrgInput.each { rec ->
    def props = rec.properties ?: rec
    def managerName = props.get('manager')?.toString()?.trim()?.toLowerCase()
    def fdeName = props.get('fde')?.toString()?.trim()
    def fdeMail = props.get('mailId')?.toString()?.trim()

    if (managerName && fdeName) {
        managerToReportsMap[managerName] << [
            fde: fdeName,
            mailId: fdeMail ?: ''
        ]
    }
}

// ================= STEP 3: Calculate Utilisation, Accounts & Direct Reports Per FDE =================
def ownerUtilisationList = fdesInput.collect { rec ->
    def props = rec.properties ?: rec
    def fdeName = props.fde?.toString()?.trim() ?: 'Unknown Owner'
    def fdeMailId = (props.get('mailId') ?: props.get('email') ?: '')?.toString()?.trim()?.toLowerCase()

    // Fetch tasks assigned to this FDE
    def assignedTasks = []
    if (fdeMailId && ownerMailTasksMap.containsKey(fdeMailId)) {
        assignedTasks = ownerMailTasksMap[fdeMailId]
    } else {
        assignedTasks = ownerMailTasksMap[fdeName.toLowerCase()] ?: []
    }

    int totalTasks = assignedTasks.size()
    int completedTasks = 0
    int inProgressTasks = 0
    int pendingTasks = 0
    def accountSet = [] as Set

    assignedTasks.each { task ->
        def status = task.status?.toString()?.toLowerCase()?.trim()
        if (status in COMPLETED_STATUSES) {
            completedTasks++
        } else if (status in IN_PROGRESS_STATUSES) {
            inProgressTasks++
        } else {
            pendingTasks++
        }

        def acct = task.account?.toString()?.trim()
        if (acct) {
            accountSet << acct
        }
    }

    int activeTasks = completedTasks + inProgressTasks
    double percentage = totalTasks ? ((activeTasks as double) / totalTasks) * 100.0 : 0.0
    double roundedPercentage = Math.round(percentage * 100) / 100.0

    // Fetch direct reports where this FDE is listed as the manager
    def directReportsList = managerToReportsMap[fdeName.toLowerCase()] ?: []
    def reportNames = directReportsList.collect { it.fde }

    def resMap = [:]
    resMap.put(OWNER_KEY, fdeName)
    resMap.put('mailId', props.mailId ?: props.email ?: '')
    resMap.put('designation', props.designation ?: 'Unknown')
    resMap.put('manager', props.manager ?: 'Unassigned')
    resMap.put('totalTasks', totalTasks)
    resMap.put('completedTasks', completedTasks)
    resMap.put('inProgressTasks', inProgressTasks)
    resMap.put('pendingTasks', pendingTasks)
    resMap.put('activeTasks', activeTasks)
    resMap.put('utilisationPercentage', roundedPercentage)
    resMap.put('utilisationFormatted', String.format("%.2f%%", roundedPercentage))
    resMap.put('totalAccounts', accountSet.size())
    resMap.put('accountNames', accountSet.toList())
    resMap.put('directReportsCount', directReportsList.size())
    resMap.put('directReportsNames', reportNames)
    resMap.put('directReportsDetails', directReportsList)

    return resMap
}

// ================= OUTPUT =================
return [result: ownerUtilisationList]
